import random
from itertools import combinations
random.seed(20240614)

def _powerset(xs):
    out = []
    for k in range(len(xs) + 1):
        for c in combinations(xs, k):
            out.append(tuple(sorted(c)))
    return sorted(out)

def _norm(lsts):
    return sorted(tuple(sorted(x)) for x in lsts)

assert subsets([]) == [[]]
assert _norm(subsets([1])) == [(), (1,)]
assert len(subsets([1, 2, 3])) == 8
for _ in range(200):
    n = random.randint(0, 7)
    nums = random.sample(range(-20, 20), n)                  # 互异元素
    got = subsets(nums)
    assert len(got) == 2 ** n                                # 恰好 2^n 个
    assert _norm(got) == _powerset(nums)                     # 与 itertools 幂集对拍
    assert len({tuple(sorted(s)) for s in got}) == len(got)  # 无重复子集

