import random
from itertools import combinations_with_replacement
random.seed(20240614)

def _brute(cands, target):
    vals = sorted({c for c in cands if c > 0})
    res = set()
    if target < 0:
        return res
    small = [c for c in vals if c <= target]
    maxk = (target // min(small)) if small else 0
    for k in range(maxk + 1):
        for comb in combinations_with_replacement(small, k):
            if sum(comb) == target:
                res.add(comb)         # cwr 在有序列表上产出非降序元组,天然规范
    return res

def _norm(lsts):
    return sorted(tuple(sorted(x)) for x in lsts)

